// Deterministic LBO calculation engine.
// AI only ever supplies the raw assumptions below — every number in this
// file is computed with plain arithmetic, never generated by a model.

export const DEFAULT_ASSUMPTIONS = {
  companyName: "Company",
  entryRevenue: 50000000,
  revenueGrowth: [0.05, 0.05, 0.05, 0.05, 0.05],
  ebitdaMargin: 0.25,
  daPct: 0.03,
  capexPct: 0.03,
  nwcPct: 0.01,
  taxRate: 0.25,
  entryMultiple: 8,
  exitMultiple: 8,
  holdingPeriod: 5,
  feePct: 0.02,
  minCash: 1000000,
  seniorDebt: { multiple: 4, rate: 0.08, amortPct: 0.01 },
  subDebt: { multiple: 2, rate: 0.11 },
  sweepPct: 0.75,
};

const num = (v, fallback) => (typeof v === "number" && Number.isFinite(v) ? v : fallback);

// Fills in anything missing/malformed from an AI-supplied assumptions object
// with the defaults above, so the engine always has a complete, well-typed input.
export function validateAssumptions(raw) {
  const a = raw && typeof raw === "object" ? raw : {};
  const growth = Array.isArray(a.revenueGrowth)
    ? Array.from({ length: 5 }, (_, i) => num(a.revenueGrowth[i], DEFAULT_ASSUMPTIONS.revenueGrowth[i]))
    : DEFAULT_ASSUMPTIONS.revenueGrowth.slice();

  const senior = a.seniorDebt && typeof a.seniorDebt === "object" ? a.seniorDebt : {};
  const sub = a.subDebt && typeof a.subDebt === "object" ? a.subDebt : {};

  const holdingPeriod = Math.round(num(a.holdingPeriod, DEFAULT_ASSUMPTIONS.holdingPeriod));

  return {
    companyName: typeof a.companyName === "string" && a.companyName.trim()
      ? a.companyName.trim()
      : DEFAULT_ASSUMPTIONS.companyName,
    entryRevenue: num(a.entryRevenue, DEFAULT_ASSUMPTIONS.entryRevenue),
    revenueGrowth: growth,
    ebitdaMargin: num(a.ebitdaMargin, DEFAULT_ASSUMPTIONS.ebitdaMargin),
    daPct: num(a.daPct, DEFAULT_ASSUMPTIONS.daPct),
    capexPct: num(a.capexPct, DEFAULT_ASSUMPTIONS.capexPct),
    nwcPct: num(a.nwcPct, DEFAULT_ASSUMPTIONS.nwcPct),
    taxRate: num(a.taxRate, DEFAULT_ASSUMPTIONS.taxRate),
    entryMultiple: num(a.entryMultiple, DEFAULT_ASSUMPTIONS.entryMultiple),
    exitMultiple: num(a.exitMultiple, DEFAULT_ASSUMPTIONS.exitMultiple),
    holdingPeriod: Math.min(5, Math.max(1, Number.isFinite(holdingPeriod) ? holdingPeriod : DEFAULT_ASSUMPTIONS.holdingPeriod)),
    feePct: num(a.feePct, DEFAULT_ASSUMPTIONS.feePct),
    minCash: num(a.minCash, DEFAULT_ASSUMPTIONS.minCash),
    seniorDebt: {
      multiple: num(senior.multiple, DEFAULT_ASSUMPTIONS.seniorDebt.multiple),
      rate: num(senior.rate, DEFAULT_ASSUMPTIONS.seniorDebt.rate),
      amortPct: num(senior.amortPct, DEFAULT_ASSUMPTIONS.seniorDebt.amortPct),
    },
    subDebt: {
      multiple: num(sub.multiple, DEFAULT_ASSUMPTIONS.subDebt.multiple),
      rate: num(sub.rate, DEFAULT_ASSUMPTIONS.subDebt.rate),
    },
    sweepPct: num(a.sweepPct, DEFAULT_ASSUMPTIONS.sweepPct),
  };
}

// Solves for the periodic rate that zeroes the NPV of a cash flow series
// (index = period, index 0 is the initial outflow) via Newton-Raphson with a
// bisection fallback for cases where the derivative is unstable.
export function irr(cashFlows, guess = 0.15) {
  const npv = (r) => cashFlows.reduce((sum, cf, t) => sum + cf / Math.pow(1 + r, t), 0);
  const dnpv = (r) => cashFlows.reduce((sum, cf, t) => (t === 0 ? sum : sum - (t * cf) / Math.pow(1 + r, t + 1)), 0);

  let r = guess;
  for (let i = 0; i < 100; i++) {
    const d = dnpv(r);
    if (Math.abs(d) < 1e-12) break;
    const next = r - npv(r) / d;
    if (!Number.isFinite(next) || next <= -0.999999) break;
    if (Math.abs(next - r) < 1e-10) { r = next; break; }
    r = next;
  }
  if (Number.isFinite(r) && Math.abs(npv(r)) < 1e-2) return r;

  // Bisection fallback over a wide, sane range.
  let lo = -0.9, hi = 10;
  let fLo = npv(lo), fHi = npv(hi);
  if (fLo * fHi > 0) return null; // no sign change — no solvable real IRR
  for (let i = 0; i < 200; i++) {
    const mid = (lo + hi) / 2;
    const fMid = npv(mid);
    if (Math.abs(fMid) < 1e-6) return mid;
    if (fLo * fMid < 0) { hi = mid; fHi = fMid; } else { lo = mid; fLo = fMid; }
  }
  return (lo + hi) / 2;
}

// Computes the full deterministic LBO: sources & uses, 5-year projections,
// the senior/sub debt schedule (interest on BEGINNING balance to avoid
// circularity), exit valuation, and sponsor MOIC/IRR.
export function computeLBO(rawAssumptions) {
  const a = validateAssumptions(rawAssumptions);

  const entryEbitda = a.entryRevenue * a.ebitdaMargin;
  const entryEV = a.entryMultiple * entryEbitda;
  const transactionFees = a.feePct * entryEV;
  const uses = entryEV + transactionFees + a.minCash;

  const seniorOriginal = a.seniorDebt.multiple * entryEbitda;
  const subOriginal = a.subDebt.multiple * entryEbitda;
  const sponsorEquity = uses - seniorOriginal - subOriginal;
  const valid = sponsorEquity > 0;

  const sourcesUses = {
    entryEbitda,
    entryEV,
    transactionFees,
    minCash: a.minCash,
    uses,
    seniorDebt: seniorOriginal,
    subDebt: subOriginal,
    sponsorEquity,
  };

  let revenue = a.entryRevenue;
  let seniorBalance = seniorOriginal;
  let subBalance = subOriginal;
  let cash = a.minCash;
  const years = [];

  for (let y = 1; y <= 5; y++) {
    revenue = revenue * (1 + a.revenueGrowth[y - 1]);
    const ebitda = revenue * a.ebitdaMargin;
    const da = revenue * a.daPct;
    const ebit = ebitda - da;

    const seniorBeginBalance = seniorBalance;
    const subBeginBalance = subBalance;
    // Interest is calculated on the beginning balance for the year, which
    // avoids a circular reference between interest, cash flow, and paydown.
    const interestExpense = seniorBeginBalance * a.seniorDebt.rate + subBeginBalance * a.subDebt.rate;

    const pretaxIncome = ebit - interestExpense;
    // No tax benefit modeled on a pretax loss.
    const taxes = Math.max(pretaxIncome, 0) * a.taxRate;
    const netIncome = pretaxIncome - taxes;

    const capex = revenue * a.capexPct;
    const nwcChange = revenue * a.nwcPct;
    const fcfForDebtPaydown = netIncome + da - capex - nwcChange;

    const mandatoryAmort = Math.min(a.seniorDebt.amortPct * seniorOriginal, seniorBeginBalance);
    const remainingAfterMandatory = fcfForDebtPaydown - mandatoryAmort;
    const excessFcf = Math.max(remainingAfterMandatory, 0);
    const cashSweep = Math.min(a.sweepPct * excessFcf, seniorBeginBalance - mandatoryAmort);

    seniorBalance = seniorBeginBalance - mandatoryAmort - cashSweep;
    // Subordinated debt is a bullet — no scheduled amortization, repaid at exit.
    subBalance = subBeginBalance;

    // Any cash flow not used for mandatory amortization or the sweep accrues
    // to the balance sheet (and a shortfall year draws it down — no revolver
    // is modeled since none was given as an assumption).
    cash = cash + (remainingAfterMandatory - cashSweep);

    const totalDebt = seniorBalance + subBalance;
    const netDebt = totalDebt - cash;

    years.push({
      year: y, revenue, ebitda, da, ebit, interestExpense, pretaxIncome, taxes, netIncome,
      capex, nwcChange, fcfForDebtPaydown, mandatoryAmort, cashSweep,
      seniorBeginBalance, seniorEndBalance: seniorBalance,
      subBeginBalance, subEndBalance: subBalance,
      cash, totalDebt, netDebt,
      debtToEbitda: ebitda > 0 ? totalDebt / ebitda : null,
      interestCoverage: interestExpense > 0 ? ebitda / interestExpense : null,
    });
  }

  const exitYear = years[a.holdingPeriod - 1];
  const exitEbitda = exitYear.ebitda;
  const exitEV = a.exitMultiple * exitEbitda;
  const exitNetDebt = exitYear.netDebt;
  const exitEquityValue = exitEV - exitNetDebt;
  const sponsorProceeds = Math.max(exitEquityValue, 0);

  const moic = valid ? sponsorProceeds / sponsorEquity : null;
  const cashFlows = new Array(a.holdingPeriod + 1).fill(0);
  cashFlows[0] = -sponsorEquity;
  cashFlows[a.holdingPeriod] = sponsorProceeds;
  const sponsorIRR = valid ? irr(cashFlows) : null;

  return {
    assumptions: a,
    sourcesUses,
    years,
    exit: { year: a.holdingPeriod, exitEbitda, exitEV, exitNetDebt, exitEquityValue, sponsorProceeds },
    returns: { moic, irr: sponsorIRR, cashFlows },
    valid,
  };
}

// Builds a symmetric range of `count` values centered on `center`, step apart.
export function sensitivityRange(center, step, count = 5) {
  const half = Math.floor(count / 2);
  return Array.from({ length: count }, (_, i) => center + (i - half) * step);
}

// 5x5 grid of sponsor IRR across entry multiple (rows) and exit multiple
// (columns). Any cell where sponsor equity would be zero or negative is
// flagged as an error instead of returning a number.
export function computeSensitivity(rawAssumptions, opts = {}) {
  const a = validateAssumptions(rawAssumptions);
  const entrySteps = opts.entrySteps ?? sensitivityRange(a.entryMultiple, 0.5, 5);
  const exitSteps = opts.exitSteps ?? sensitivityRange(a.exitMultiple, 0.5, 5);

  const grid = entrySteps.map((entryMultiple) =>
    exitSteps.map((exitMultiple) => {
      const result = computeLBO({ ...a, entryMultiple, exitMultiple });
      if (!result.valid) {
        return { entryMultiple, exitMultiple, error: true, irr: null };
      }
      return { entryMultiple, exitMultiple, error: false, irr: result.returns.irr };
    })
  );

  return { entrySteps, exitSteps, grid };
}
